import openpyxl

wb = openpyxl.load_workbook('sales_data.xlsx')
for ws in wb.worksheets:
    print(f"Sheet: {ws.title}, dims: {ws.dimensions}, max_row: {ws.max_row}, max_col: {ws.max_column}")
    for row in ws.iter_rows(min_row=1, max_row=min(ws.max_row, 15)):
        vals = []
        for c in row:
            vals.append(f"{c.coordinate}={c.value!r}")
        print(" | ".join(vals))

import importlib
for mod in ['pandas', 'openpyxl', 'xlrd', 'xlsxwriter', 'odf']:
    try:
        m = importlib.import_module(mod)
        print(mod, 'OK', getattr(m, '__version__', ''))
    except Exception as e:
        print(mod, 'MISSING', e)

